<script setup lang="ts">
import {onMounted,ref} from 'vue'
function reloadOptions(){location.reload()}
const passwordChanged=new URLSearchParams(location.search).has('password_changed')
const props=defineProps<{mode:string;returnTo?:string}>(),options=ref<any>(null),username=ref(''),displayName=ref(''),password=ref(''),error=ref(''),busy=ref(false),loading=ref(true)
async function getOptions(){const r=await fetch('/api/v1/auth/options',{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw new Error('登录服务暂不可用，请稍后重试。');return r.json()}
onMounted(async()=>{try{options.value=await getOptions()}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
async function submit(){if(busy.value)return;error.value='';const length=Array.from(password.value).length;if(length<15||length>1024||new TextEncoder().encode(password.value).length>4096){error.value='密码需为 15–1024 个字符，且不超过 4096 字节。';return}busy.value=true;try{options.value=await getOptions();const registering=props.mode==='register';const r=await fetch('/api/v1/auth/'+(registering?'register':'login'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':options.value.csrf_token},body:JSON.stringify({username:username.value.trim().toLowerCase(),password:password.value,...(registering?{display_name:displayName.value.trim()}:{})})});if(!r.ok){const data=await r.json();throw new Error(r.status===401?'用户名或密码不正确。':r.status===429?'尝试过于频繁，请稍后再试。':data.error?.message||'未能完成，请重试。')}const target=props.returnTo||'/me';location.assign(target.startsWith('/')&&!target.startsWith('//')?target:'/me')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div><p v-if="mode==='login'&&passwordChanged" class="notice" role="status">密码已更新，请重新登录。</p><div v-if="loading" class="loading-line" aria-label="正在读取登录选项"></div><p v-if="error" class="notice error" role="alert">{{error}}</p><button v-if="!loading&&!options" class="button" @click="reloadOptions">重新加载登录表单</button><template v-if="options"><p v-if="mode==='register'&&!options.registration_open" class="notice">当前暂停注册，已有账号可以继续登录。</p><form v-else class="auth-form" @submit.prevent="submit"><label>用户名<input v-model="username" required minlength="2" maxlength="64" pattern="[A-Za-z0-9][A-Za-z0-9_-]{1,63}" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="字母、数字、下划线或连字符"></label><label v-if="mode==='register'">显示名称<input v-model="displayName" required maxlength="100" autocomplete="nickname" placeholder="读者会看到的名字"></label><label>密码<input v-model="password" required type="password" :autocomplete="mode==='register'?'new-password':'current-password'" :aria-describedby="mode==='register'?'password-hint':undefined"></label><small v-if="mode==='register'" id="password-hint">使用 15–1024 个字符。建议使用容易记住的长密码，首尾空格也会保留。</small><button class="primary" :disabled="busy">{{busy?'请稍候…':mode==='register'?'注册账号':'登录'}}</button></form><div class="auth-alternatives"><a v-if="mode==='login'&&options.registration_open" :href="'/register?return_to='+encodeURIComponent(returnTo||'/me')">创建账号</a><a v-if="mode==='register'" :href="'/login?return_to='+encodeURIComponent(returnTo||'/me')">已有账号？登录</a><a v-if="options.github_login_enabled" class="button" :href="'/auth/github/start?return_to='+encodeURIComponent(returnTo||'/me')">使用 GitHub 继续</a></div><p v-if="mode==='login'" class="auth-help">忘记密码？请联系站点管理员重置。</p></template></div></template>
